def P(fact, kind, word, hint, spot, challenge=None):
    return dict(fact=fact, puzzle=(kind, word, hint), spot=spot, challenge=challenge)


def R(fact, clue, spot, challenge=None):
    return dict(fact=fact, clue=clue, spot=spot, challenge=challenge)


